def aprofundar(perfis):
    for perfil in perfis:
        data = DADOS_PERFIS[perfil['id']]
        sections = data['seccoes']
        perfil.update(resumo=data['resumo'], ficha=data['ficha'],
                      seccoes=[(s['titulo'], s['texto']) for s in sections],
                      ids_seccoes=[s['id'] for s in sections],
                      fontes_seccoes=[s['fontes'] for s in sections],
                      fontes=list(dict.fromkeys(key for s in sections for key in s['fontes'])))
